#include <queue>
#include <cassert>
#include <iostream>

int main() {
    std::priority_queue<int> values;
    values.push(2);
    values.push(7);
    assert(values.top() == 7);

    std::priority_queue<int> copy;
    copy = values;
    assert(copy.top() == values.top());
    values.pop();
    assert(values.top() == 2);
    std::cout << "Checks passed\n";
}
